<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class Wallet extends Model { use \Illuminate\Database\Eloquent\Concerns\HasUuids; public $incrementing=false; protected $keyType='string'; protected $fillable=['user_id','owner_id','currency_id','label','nickname','status','wallet_type']; public function user(): BelongsTo { return $this->belongsTo(User::class); } public function currency(): BelongsTo { return $this->belongsTo(Currency::class); } public function owner(): BelongsTo { return $this->belongsTo(WalletOwner::class,'owner_id'); } public function currencyAccounts(): \Illuminate\Database\Eloquent\Relations\HasMany { return $this->hasMany(WalletCurrencyAccount::class); } public function preferences(): \Illuminate\Database\Eloquent\Relations\HasOne { return $this->hasOne(WalletPreference::class); } public function statusHistory(): \Illuminate\Database\Eloquent\Relations\HasMany { return $this->hasMany(WalletStatusHistory::class); } }
